import numpy as np
one=np.ones_like(t)
X=np.column_stack([one,1/A,A,A**2,t**2/A])
c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
r=dA_dt-X@c
lib={}
for fn,f in [("1",one),("t",t),("t2",t**2),("1/t",1/t),("exp(-t)",np.exp(-t)),("exp(t/5)",np.exp(t/5)),("sin t",np.sin(t)),("cos t",np.cos(t)),("log t",np.log(t)),("sqrt t",np.sqrt(t))]:
  for gn,g in [("1",one),("A",A),("1/A",1/A),("A2",A**2),("1/A2",1/A**2),("logA",np.log(A)),("sqrtA",np.sqrt(A)),("expA",np.exp(-A))]:
    v=f*g
    if np.std(v)<1e-9: continue
    cc=np.corrcoef(v,r)[0,1]
    lib[f"{fn}*{gn}"]=cc
for k,v in sorted(lib.items(), key=lambda x:-abs(x[1]))[:10]: print(k, round(v,3))

